steps.script:
var objs = []
for obj in TerrainManager.layout_objectives:
	var pos = obj.get("position", [0, 0])
	objs.append({"id": str(obj.id), "position": Vector2(pos[0] * 40.0, pos[1] * 40.0), "radius_mm": 40, "zone": str(obj.get("zone", "no_mans_land")), "source_pieces": obj.get("source_pieces", []).duplicate()})
GameState.state.board["objectives"] = objs
var tel = GameState.state.units["U_TELEMON_HEAVY_DREADNOUGHT_I"]
tel.flags["moved"] = true
var wc = GameState.state.units["U_WITCHSEEKERS_C"]
var i = 0
for m in wc.models:
	m["position"] = {"x": 1020.0 + i * 45.0, "y": 470.0}
	i += 1
wc.flags["moved"] = true
var ws = GameState.state.units["U_WITCHSEEKERS_D"]
for k in ["moved", "advanced", "fell_back", "remained_stationary", "has_shot", "cannot_charge", "move_cap_inches"]:
	ws.flags.erase(k)
i = 0
for m in ws.models:
	m["position"] = {"x": 700.0 + i * 45.0, "y": 900.0}
	i += 1
for o in objs:
	var v = MissionManager.objectives_visual_refs.get(o.id)
	if v != null:
		for c in v.get_children():
			c.free()
		v.setup(o)
tree.root.get_node("Main")._recreate_unit_visuals()
return "%.1f" % (AIDecisionMaker._unit_gap_to_objective_px(ws, Vector2(260, 750)) / 40.0)

var ws = GameState.state.units["U_WITCHSEEKERS_D"]
var nml = {}
for o in GameState.state.board.objectives:
	if o.id == "obj_nml_1":
		nml = o
var on := false
for m in ws.models:
	if m.get("alive", true) and MissionManager.model_in_objective_range(m, nml):
		on = true
return on and bool(ws.flags.get("advanced", false))

var m1 = GameState.state.units["U_WITCHSEEKERS_D"].models[0]
var v = Vector2(float(m1.position.x) - 700.0, float(m1.position.y) - 900.0)
var deg = absf(rad_to_deg(atan2(-v.y, -v.x)))
return "straight" if v.x < 0.0 and deg < 8.0 else "angle %.1f deg" % deg
